# Lambda blog post and CoreWeave whitepaper page on MLPerf Training v6.0, held against the result logs of rounds 5.0, 5.1 and 6.0. python3 -I check_claims_training_posts_v60.py
import json,hashlib
FILES=['training_v50_times.json','training_v51_times.json','training_v60_times.json']
RAW={f:open(f,'rb').read() for f in FILES}; R={v:json.loads(RAW[f]) for v,f in zip(('50','51','60'),FILES)}; s=str
def one(v,sub,sysn,bench):
    r=[o for o in R[v] if o['submitter']==sub and o['system']==sysn and o['benchmark']==bench]; assert len(r)==1,(v,sub,sysn,bench,len(r)); return r[0]['official_style']
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
L=[]; W=[]
lg=one('60','Lambda','gb300_n18_ngc25.09_nemo','llama31_8b'); lg0=one('51','Lambda','gb300_n18_ngc25.04_nemo','llama31_8b')
L.append(mk('LM1','Our GB300 NVL72 system converges in 11.59 minutes, compared to 14.25 minutes in Training v5.1. This represents an 18.7% improvement in training speed','Lambda 72-GPU GB300 Llama 3.1 8B, round 5.1 entry against round 6.0 entry, official-style time to train','11.59 and 14.25 minutes, 18.7%',f'{lg:.3f} min against {lg0:.3f} min, {100*(1-lg/lg0):.1f}% shorter ({lg0/lg:.2f}x)','CONSISTENT' if abs(lg-11.59)<0.01 and abs(lg0-14.25)<0.01 and abs(100*(1-lg/lg0)-18.7)<0.1 else 'BELOW','The 18.7% is the reduction in time to train. As a speedup it is 23.0%.'))
t=[('llama31_8b','gb300_n18_ngc25.09_nemo',11.59),('llama31_8b','b200_n1_ngc25.09_nemo',85.26),('gpt_oss_20b','gb300_n18_ngc25.09_nemo',18.35),('gpt_oss_20b','b200_n1_ngc25.09_nemo',96.46)]
got=[one('60','Lambda',sn,b) for b,sn,_ in t]
L.append(mk('LM2','Lambda results table in the post','Lambda entries in round 6.0','11.59, 85.26, 18.35 and 96.46 minutes','; '.join(f'{b} {sn.split("_")[0]} {g:.3f}' for (b,sn,_),g in zip(t,got)),'CONSISTENT' if all(abs(g-x[2])<0.011 for g,x in zip(got,t)) else 'BELOW','The GPT-OSS-20B GB300 time is 18.359 in the log summary against 18.35 in the post.'))
gb=sorted([o for o in R['60'] if o['benchmark']=='llama31_8b' and 'GB300' in s(o['accelerator']) and o['gpus']==72],key=lambda o:o['official_style'])
L.append(mk('LM3','Lambda completed training in 11.59 minutes on a GB300 NVL72 system, the fastest result among all GB300 NVL72 systems submitted this round, edging the NVIDIA Theia system single-rack submission (11.75 min), HPE (11.82 min), GigaComputing (11.84 min), and Nebius (11.87 min).','every 72-GPU GB300 Llama 3.1 8B entry in round 6.0','fastest, with 11.75, 11.82, 11.84 and 11.87 behind',', '.join(f'{o["submitter"]} {o["official_style"]:.3f}' for o in gb[:6]),'CONSISTENT' if gb[0]['submitter']=='Lambda' and sorted(round(o['official_style'],2) for o in gb if o['submitter'] in('NVIDIA','HPE','GigaComputing','Nebius'))==[11.75,11.82,11.84,11.87] else 'BELOW','NVIDIA also has a 512-GPU GB300 entry at 4.636 min. The comparison is among single-rack entries. A Supermicro entry at 11.860 also sits behind Lambda and is not named in the post.'))
b8=sorted([o for o in R['60'] if o['benchmark']=='gpt_oss_20b' and 'B200' in s(o['accelerator']) and 'GB200' not in s(o['accelerator']) and o['gpus']==8],key=lambda o:o['official_style'])
L.append(mk('LM4','Lambda achieved the fastest result among single-node HGX B200 submissions for GPT-OSS-20B.','8-GPU B200 GPT-OSS-20B entries in round 6.0','fastest among single-node HGX B200',', '.join(f'{o["submitter"]} {o["official_style"]:.3f}' for o in b8),'CONSISTENT' if b8[0]['submitter']=='Lambda' else 'BELOW','The margin over the next entry is 1.4%.'))
g72=sorted([o for o in R['60'] if o['benchmark']=='gpt_oss_20b' and 'GB300' in s(o['accelerator']) and o['gpus']==72],key=lambda o:o['official_style']); rk=[o['submitter'] for o in g72].index('Lambda')+1
L.append(mk('LM5','Lambda converged in 18.35 minutes, among the fastest of the GB300 NVL72 single-rack systems.','every 72-GPU GB300 GPT-OSS-20B entry in round 6.0','among the fastest',f'Rank {rk} of {len(g72)}: '+', '.join(f'{o["submitter"]} {o["official_style"]:.3f}' for o in g72)+f'. Lambda is {100*(g72[rk-1]["official_style"]/g72[0]["official_style"]-1):.1f}% behind the first','CANNOT_TELL','The statement is a judgment. The spread across the group is under 2%.'))
gs=sorted({o['submitter'] for o in R['60'] if 'GB300' in s(o['accelerator'])})
L.append(mk('LM6','Eight teams reported official GB300 NVL72 results this round: Lambda, Nebius, CoreWeave, Oracle, Dell, GigaComputing, HPE, and NVIDIA.','submitters with a GB300 accelerator in round 6.0','eight teams',f'{len(gs)} submitters: '+', '.join(gs),'CANNOT_TELL' if len(gs)!=8 else 'CONSISTENT','Supermicro and Quanta Cloud Technology are in the file with GB300 entries and are not on the list. Whether their systems count as NVL72 is not stated in the file.'))
nb=lambda v:{o['benchmark'] for o in R[v]}
L.append(mk('LM7','Llama 3.1 8B was introduced in the previous round (MLPerf Training v5.1)','benchmarks present in rounds 5.0, 5.1 and 6.0','introduced in v5.1',f'Llama 3.1 8B in round 5.0: {"llama31_8b" in nb("50")}. In round 5.1: {"llama31_8b" in nb("51")}','CONSISTENT' if ('llama31_8b' not in nb('50') and 'llama31_8b' in nb('51')) else 'BELOW',''))
moe={"gpt_oss_20b","deepseekv3_671b"}
L.append(mk('LM8',"GPT-OSS-20B, along with DeepSeek-V3, is one of MLPerf's first mixture-of-experts benchmarks.",'benchmarks present in rounds 5.0, 5.1 and 6.0','first mixture-of-experts benchmarks','Both appear in round 6.0 only. Present in round 5.0: '+str(bool(moe&nb("50")))+'. Present in round 5.1: '+str(bool(moe&nb("51")))+'. Present in round 6.0: '+str(moe<=nb("60")),'CONSISTENT' if not (moe&(nb('50')|nb('51'))) and moe<=nb('60') else 'BELOW','Rounds before 5.0 are not read.'))
# CoreWeave
cw=[o for o in R['60'] if o['submitter']=='CoreWeave']; d=[o for o in cw if o['benchmark']=='deepseekv3_671b' and o['gpus']==8192][0]; fast=sorted([(o['official_style'],o['submitter'],o['gpus']) for o in R['60'] if o['benchmark']=='deepseekv3_671b'])[0]
W.append(mk('CW1',"CoreWeave trained DeepSeek-V3 671B to the benchmark's quality target in 2.02 minutes on 8,192 NVIDIA GB300 NVL72 GPUs. It was the fastest result in the round on that benchmark.",'CoreWeave DeepSeek-V3 671B entries and every other DeepSeek-V3 entry in round 6.0','2.02 minutes on 8,192 GPUs, fastest in the round',f'{d["official_style"]:.3f} min on {d["gpus"]} GPUs. Fastest in the round: {fast[1]} {fast[0]:.3f} min on {fast[2]} GPUs. Next: '+', '.join(f'{b} {a:.3f} ({g} GPUs)' for a,b,g in sorted([(o["official_style"],o["submitter"],o["gpus"]) for o in R["60"] if o["benchmark"]=="deepseekv3_671b"])[1:3]),'CONSISTENT' if abs(d['official_style']-2.02)<0.01 and fast[1]=='CoreWeave' else 'BELOW',''))
p=[o for o in R['50'] if o['benchmark']=='llama31_405b' and abs(o['official_style']-27.33)<0.01][0]; c=[o for o in cw if o['benchmark']=='llama31_405b'][0]
W.append(mk('CW2','A year-over-year read on Llama 3.1 405B, where time-to-train dropped 2.8x, from 27.33 minutes to 9.77 minutes','round 5.0 entry at 27.33 minutes and CoreWeave round 6.0 Llama 3.1 405B entry','2.8x, 27.33 to 9.77 minutes',f'{p["submitter"]} {p["system"]} ({p["gpus"]} GPUs) {p["official_style"]:.3f} min against CoreWeave {c["gpus"]} GPUs {c["official_style"]:.3f} min = {p["official_style"]/c["official_style"]:.2f}x','CONSISTENT' if abs(p['official_style']/c['official_style']-2.8)<0.05 else 'BELOW','The earlier entry is a joint submission (IBM, CoreWeave, NVIDIA) on 2,496 GPUs. The later one uses 4,096 GPUs.'))
sysn={o['system'] for o in cw}; gp=sorted({o['gpus'] for o in cw})
W.append(mk('CW3','It walks through how CoreWeave scaled frontier training across five system configurations, from 64 GPUs to 8,192','CoreWeave entries in round 6.0','five system configurations, 64 to 8,192 GPUs',f'{len(sysn)} systems, GPU counts {gp}','CONSISTENT' if len(sysn)==5 and gp[0]==64 and gp[-1]==8192 else 'BELOW',''))
for nm,Lx in (('claims_lambda_training_v60.json',L),('claims_coreweave_training_v60.json',W)):
    json.dump(dict(source=FILES,sha256=[hashlib.sha256(RAW[f]).hexdigest() for f in FILES],claims=Lx),open(nm,'w'),indent=1)
    for x in Lx: print(x['id'],x['outcome'],'|',x['stated'],'|',x['delivered'][:200])
